import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { beforeEach, describe, expect, it, vi } from 'vitest';

const entries = new Map<string, string>();
const keytar = vi.hoisted(() => ({
  getPassword: vi.fn(),
  setPassword: vi.fn(),
  deletePassword: vi.fn(),
}));
vi.mock('../src/keyring.js', () => ({ getKeytar: async () => keytar }));
const configDir = vi.hoisted(() => ({ path: '' }));
vi.mock('../src/constants.js', () => ({
  get CONFIG_DIR() {
    return configDir.path;
  },
}));

import { loadAgentCredentials, saveAgentCredentials } from '../src/agent-credentials.js';

const credentials = {
  registrationId: 'reg_1',
  issuer: 'https://auth.example.com',
  assertion: 'assertion',
  claimToken: 'claim',
};

describe('agent credentials', () => {
  beforeEach(() => {
    entries.clear();
    vi.resetAllMocks();
    configDir.path = fs.mkdtempSync(path.join(os.tmpdir(), 'mint-agent-'));
    keytar.getPassword.mockImplementation(
      async (service, account) => entries.get(`${service}/${account}`) ?? null
    );
    keytar.setPassword.mockImplementation(async (service, account, value) => {
      entries.set(`${service}/${account}`, value);
    });
    keytar.deletePassword.mockImplementation(async (service, account) =>
      entries.delete(`${service}/${account}`)
    );
  });

  it('isolates projects and environments from each other and human credentials', async () => {
    await saveAgentCredentials('https://api.example.com', '/docs', credentials);
    expect(await loadAgentCredentials('https://api.example.com', '/docs')).toEqual(credentials);
    expect(await loadAgentCredentials('https://dev.example.com', '/docs')).toBeNull();
    expect(await loadAgentCredentials('https://api.example.com', '/other')).toBeNull();
    expect([...entries.keys()].every((key) => key.startsWith('mintlify-agent/'))).toBe(true);
  });

  it('retains old registrations when the current project starts a new site', async () => {
    await saveAgentCredentials('https://api.example.com', '/docs', credentials);
    await saveAgentCredentials('https://api.example.com', '/docs', {
      ...credentials,
      registrationId: 'reg_2',
    });
    expect((await loadAgentCredentials('https://api.example.com', '/docs'))?.registrationId).toBe(
      'reg_2'
    );
    expect(entries.has('mintlify-agent/https://api.example.com:reg_1')).toBe(true);
  });

  it('falls back to a local file when the keyring cannot be written or read', async () => {
    keytar.setPassword.mockRejectedValue(new Error('locked'));
    await saveAgentCredentials('https://api.example.com', '/docs', credentials);
    expect(entries.size).toBe(0);
    const file = path.join(configDir.path, 'agent-credentials.json');
    if (process.platform !== 'win32') expect(fs.statSync(file).mode & 0o777).toBe(0o600);
    keytar.getPassword.mockRejectedValue(new Error('locked'));
    expect(await loadAgentCredentials('https://api.example.com', '/docs')).toEqual(credentials);
  });

  it('removes stale fallback entries once the keyring is writable again', async () => {
    keytar.setPassword.mockRejectedValueOnce(new Error('locked'));
    await saveAgentCredentials('https://api.example.com', '/docs', credentials);
    await saveAgentCredentials('https://api.example.com', '/docs', {
      ...credentials,
      assertion: 'next',
    });
    expect((await loadAgentCredentials('https://api.example.com', '/docs'))?.assertion).toBe(
      'next'
    );
    const file = path.join(configDir.path, 'agent-credentials.json');
    expect(JSON.parse(fs.readFileSync(file, 'utf-8'))).toEqual({});
  });

  it('reads the keyring before the fallback file', async () => {
    await saveAgentCredentials('https://api.example.com', '/docs', credentials);
    fs.writeFileSync(
      path.join(configDir.path, 'agent-credentials.json'),
      JSON.stringify({
        'https://api.example.com:reg_1': JSON.stringify({ ...credentials, assertion: 'stale' }),
      })
    );
    expect(await loadAgentCredentials('https://api.example.com', '/docs')).toEqual(credentials);
  });

  it('ignores a corrupt fallback file when the keyring has the credentials', async () => {
    await saveAgentCredentials('https://api.example.com', '/docs', credentials);
    fs.writeFileSync(path.join(configDir.path, 'agent-credentials.json'), '{');
    expect(await loadAgentCredentials('https://api.example.com', '/docs')).toEqual(credentials);
  });

  it('drops the stale keyring entry when a write falls back to the file', async () => {
    await saveAgentCredentials('https://api.example.com', '/docs', credentials);
    keytar.setPassword.mockRejectedValueOnce(new Error('locked'));
    await saveAgentCredentials('https://api.example.com', '/docs', {
      ...credentials,
      assertion: 'next',
    });
    expect((await loadAgentCredentials('https://api.example.com', '/docs'))?.assertion).toBe(
      'next'
    );
  });

  it('succeeds when the keyring write works but fallback cleanup fails', async () => {
    keytar.setPassword.mockRejectedValueOnce(new Error('locked'));
    await saveAgentCredentials('https://api.example.com', '/docs', credentials);
    fs.chmodSync(configDir.path, 0o500);
    await expect(
      saveAgentCredentials('https://api.example.com', '/docs', {
        ...credentials,
        assertion: 'next',
      })
    ).resolves.toBeUndefined();
    fs.chmodSync(configDir.path, 0o700);
    expect((await loadAgentCredentials('https://api.example.com', '/docs'))?.assertion).toBe(
      'next'
    );
  });

  it('fails when neither the keyring nor the local file can be written', async () => {
    keytar.setPassword.mockRejectedValue(new Error('locked'));
    configDir.path = path.join(configDir.path, 'not-a-directory');
    fs.writeFileSync(configDir.path, '');
    await expect(
      saveAgentCredentials('https://api.example.com', '/docs', credentials)
    ).rejects.toThrow();
  });

  it('preserves read failures instead of treating them as an absent registration', async () => {
    keytar.getPassword.mockRejectedValueOnce(new Error('locked'));
    await expect(loadAgentCredentials('https://api.example.com', '/docs')).rejects.toThrow(
      'locked'
    );
  });
});
